s=s.replace('["Invoice Processing", "Apply confidence checks, tax validation, and HIL review when required.", "5 metadata fields", "#0d9f9c", Coins],\n  ["Invoice Processing", "Deliver validated invoice metadata to downstream payable workflows.", "30s target SLA", "#8b5ac7", Send],','["Referral Creation", "Classify referral documents and route complete referral packets for review.", "Conditional HIL", "#0d9f9c", Coins],\n  ["Payment Posting", "Validate remittance details and deliver posting-ready metadata downstream.", "30s target SLA", "#8b5ac7", Send],')
old='<div className="mt-3 space-y-2.5 text-[10px]"><div className="flex items-center justify-between"><span className="text-slate-400">{selectedNodeIndex === 0 ? "Connector" : "Output connector"}</span><span className="font-semibold text-[#142b4b]">Amazon S3</span></div><div className="flex items-center justify-between gap-3"><span className="text-slate-400">Integration</span><span className="text-right font-semibold text-[#142b4b]">Client 1 — {selectedNodeIndex === 0 ? "Invoice Intake" : "Invoice Output"}</span></div><div className="flex items-center justify-between"><span className="text-slate-400">Bucket</span><span className="font-mono font-semibold text-[#142b4b]">{selectedNodeIndex === 0 ? "client-1-invoices" : "client-1-output"}</span></div><div className="flex items-center justify-between"><span className="text-slate-400">Path</span><span className="font-mono font-semibold text-[#142b4b]">{selectedNodeIndex === 0 ? "/incoming/" : "/processed/"}</span></div></div></div>}'
new='<div className="mt-3 space-y-2.5 text-[10px]">{(selectedNodeIndex === 0 ? [["Connector", "inputConnector"], ["Integration", "inputIntegration"], ["Bucket", "inputBucket"], ["Path", "inputPath"]] : [["Output connector", "outputConnector"], ["Integration", "outputIntegration"], ["Bucket", "outputBucket"], ["Path", "outputPath"]]).map(([label, key]) => <label key={key} className="block"><span className="mb-1 block text-slate-400">{label}</span><input value={connectorConfig[key]} onChange={(e) => { setConnectorConfig({ ...connectorConfig, [key]: e.target.value }); setConnectorSaved(false); }} className="h-8 w-full rounded-lg border border-blue-100 bg-white px-2.5 font-mono text-[10px] font-semibold text-[#142b4b] outline-none focus:border-blue-400" /></label>)}<button onClick={() => { setConnectorSaved(true); toast.success("Connector changes saved"); }} className={cn("mt-1 inline-flex items-center gap-1.5 rounded-lg px-3 py-2 text-[9px] font-bold", connectorSaved ? "bg-emerald-50 text-emerald-700" : "bg-blue-600 text-white")}>{connectorSaved ? "Saved" : "Save connector changes"}</button></div></div>}'
