new_auth='<div className="block"><span className="mb-2 block text-[10px] font-bold text-slate-500">{entryMode === "central" ? "Platform scope" : "Authorized workspace"}</span><div className="flex h-11 items-center justify-between rounded-xl border border-slate-200 bg-slate-50 px-3 text-[11px] font-semibold text-slate-700"><span>{entryMode === "central" ? "PACCA Platform" : "Client 1"}</span><span className="text-[9px] font-bold text-emerald-600">Authorized</span></div></div>'
